def extract(self) -> Dict[str, Any]:
    try:
        tree = ast.parse(self.source_code, filename=self.file_path)
    except SyntaxError as e:
        return {
            "file": self.rel_path,
            "error": f"SyntaxError: {e.msg} at line {e.lineno}",
            "classes": [],
            "functions": [],
            "imports": [],
            "docstring": "",
            "loc": len(self.lines)
        }

    module_doc = ast.get_docstring(tree) or ""
    imports = []
    classes = []
    functions = []

    # Top-level AST walk
    for node in tree.body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports.append({
                    "module": alias.name,
                    "alias": alias.asname or alias.name,
                    "line": node.lineno
                })
        elif isinstance(node, ast.ImportFrom):
            mod = node.module or ""
            for alias in node.names:
                imports.append({
                    "module": f"{mod}.{alias.name}" if mod else alias.name,
                    "alias": alias.asname or alias.name,
                    "line": node.lineno
                })
        elif isinstance(node, ast.ClassDef):
            classes.append(self._parse_class(node))
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            functions.append(self._parse_function(node))

    return {
        "file": self.rel_path,
        "docstring": module_doc.strip(),
        "loc": len(self.lines),
        "imports": imports,
        "classes": classes,
        "functions": functions
    }

